public class GUPAttributeBasedPricingDataManager
extends GUPRetailPricingDataManager
    implements Microsoft.Dynamics.Commerce.Runtime.Services.AttributeBasedPricingEngine.IAttributeBasedPricingDataAccessor
{
    private Microsoft.Dynamics.Commerce.Runtime.DataModel.AttributeBasedPricing.AttributeBasedPricingParameter attributeBasedPricingParameter;

}

Method.Source:
public void new(RecId _channelRecordId, RetailTransactionId _transactionId, RetailTempOrderItem _tempOrderItem = null, boolean _isTempOrderItemFilled = false)
{
    super(_channelRecordId, _transactionId, _tempOrderItem, _isTempOrderItemFilled);
    attributeBasedPricingParameter = new Microsoft.Dynamics.Commerce.Runtime.DataModel.AttributeBasedPricing.AttributeBasedPricingParameter();
    attributeBasedPricingParameter.IsEnabled = true;
    attributeBasedPricingParameter.ShouldFindNextTradeAgreement = GUPParameters::find().PriceDiscSearchAgainDefault;
    attributeBasedPricingParameter.FreeItemCalculationBase = GUPParameters::find().FreeItemCalculationBase;
    attributeBasedPricingParameter.FreeItemConcurrencyControlModel = GUPParameters::find().FreeItemConcurrencyControlModel;
}

protected Microsoft.Dynamics.Commerce.Runtime.DataModel.PeriodicDiscount ConvertToCrtPeriodicDiscountV2(
    RetailPeriodicDiscount periodicDiscount,
    RetailPeriodicDiscountLine periodicDiscountLine,
    UnitOfMeasure unitOfMeasure,
    int discountType,
    ItemId itemId,
    InventDimId inventDimId)
{
    Microsoft.Dynamics.Commerce.Runtime.DataModel.AttributeBasedPricing.AttributeBasedPeriodicDiscount crtDiscount = 
        super(periodicDiscount, periodicDiscountLine, unitOfMeasure, discountType, itemId, inventDimId)
        as Microsoft.Dynamics.Commerce.Runtime.DataModel.AttributeBasedPricing.AttributeBasedPeriodicDiscount;

    if (crtDiscount != null && periodicDiscount.PeriodicDiscountType == RetailDiscountOfferTypeBase::FreeItem)
    {
        GUPFreeItemDiscount freeItemDiscount = periodicDiscount;
        crtDiscount.FreeItemCriteriaType = enum2int(freeItemDiscount.FreeItemCriteriaType);
        crtDiscount.IsFreeItemRepeatable = freeItemDiscount.FreeItemRepeatable;
        crtDiscount.FreeItemMethod = enum2int(freeItemDiscount.FreeItemCalculationMethod);

        GUPFreeItemDiscountLine freeItemDiscountLine = periodicDiscountLine;
        crtDiscount.FreeItemGroupId = freeItemDiscountLine.FreeItemGroup;
        crtDiscount.IsMandatory = freeItemDiscountLine.IsMandatory;
        crtDiscount.AmountThreshold = freeItemDiscountLine.LeastAmount;
    }

    return crtDiscount;
}

/// <summary>
/// Fetches all free items
/// </summary>
/// <param name="items">The set of items to search by. Set of pairs of item Id and variant dimension Id. Ignores the unit.</param>
/// <param name="minActiveDate">The earliest inclusive active date to search by. Must be less than or equal to maxActiveDate.</param>
/// <param name="maxActiveDate">The latest inclusive active date to search by. Must be greater than or equal to minActiveDate.</param>
/// <param name="currencyCode">Currency code to filter by.</param>
/// <param name="settings">The query result settings.</param>
/// <returns>The first value is a collection of price adjustments striped by item Id and variant dimension Id (if any), the second value represents all the validation periods used by the discovered price adjustments..</returns>
public System.Object ReadGlobalUnifiedPricingFreeItems(
           System.Object items,
           System.DateTimeOffset minActiveDate,
           System.DateTimeOffset maxActiveDate,
           System.String currencyCode,
           Microsoft.Dynamics.Commerce.Runtime.DataModel.QueryResultSettings settings)
{
    ValidFromDate minFromDate =  this.GetDateInChannelTimeZone(minActiveDate);
    ValidFromDate maxToDate =  this.GetDateInChannelTimeZone(maxActiveDate);

    CLRObject discountList = this.createCLRList(new Microsoft.Dynamics.Commerce.Runtime.DataModel.AttributeBasedPricing.AttributeBasedPeriodicDiscount());

    RetailPeriodicDiscount promo;
    select firstonly RecId from promo
        where  promo.Status == RetailDisabledEnabled::Enabled
               && promo.IsGupDiscount == NoYes::Yes
               && promo.PeriodicDiscountType == RetailDiscountOfferTypeBase::FreeItem
               && ((promo.ValidFrom <= minFromDate || promo.ValidFrom <= noDate)
               && (promo.ValidTo >= maxToDate || promo.ValidTo <= noDate));
    if (!promo)
    {
        return discountList.AsReadOnly();
    }

    Map validationPeriodLookup = new Map(Types::String, Types::AnyType);
    this.readFreeItems(discountList, minFromDate, maxToDate, validationPeriodLookup);
    return discountList.AsReadOnly();
}

private void readFreeItems(
    CLRObject _priceDataList,
    ValidFromDate _minFromDate,
    ValidFromDate _maxToDate,
    Map _validationPeriodLookup)
{
    GUPPriceComponentCode priceComponentCode;
    GUPPriceComponentCodeSetup priceComponentCodeSetup;
    RetailPeriodicDiscount periodicDiscount;
    RetailPeriodicDiscountLine periodicDiscountLine;
    UnitOfMeasure unitOfMeasure;
    InventDim inventDim;

    GUPPriceComponentCodePriceAttributeGroupCombination groupCombination;
    GUPPricingRule pricingRuleHeader, pricingRuleLine;
    GUPPricingAttributeGroup pricingAttributeGroupHeader, pricingAttributeGroupLine;

    int discountType = 0;

    Microsoft.Dynamics.Commerce.Runtime.DataModel.AttributeBasedPricing.AttributeBasedPeriodicDiscount crtDiscount;
    Microsoft.Dynamics.Commerce.Runtime.DataModel.PricingComponentCode crtPricingComponentCode;

    delete_from mTmpOrderData;

    //RecId gupPriceTreeRecId = GUPPricingTree::find(this.unifiedPricingParameter.PriceTreeName).RecId;

    while select priceComponentCodeSetup
        join periodicDiscount
        where priceComponentCodeSetup.PriceComponentCodeName == periodicDiscount.PriceComponentCodeName
           //&& priceComponentCodeSetup.PricingTree == gupPriceTreeRecId
           && periodicDiscount.Status == RetailDisabledEnabled::Enabled
           && periodicDiscount.IsGupDiscount == NoYes::Yes
           && periodicDiscount.PeriodicDiscountType == RetailDiscountOfferTypeBase::FreeItem
           && ((periodicDiscount.ValidFrom <= _minFromDate || periodicDiscount.ValidFrom <= noDate)
           && (periodicDiscount.ValidTo >= _maxToDate || periodicDiscount.ValidTo <= noDate))
        join periodicDiscountLine
            where periodicDiscount.OfferId == periodicDiscountLine.OfferId
        join priceComponentCode
            where priceComponentCodeSetup.PriceComponentCodeName == priceComponentCode.Name
        join RecId, Priority from groupCombination
            where groupCombination.RecId == periodicDiscountLine.PriceAttributeGroupCombinationRecId
        outer join inventDim
            where inventDim.inventDimId == periodicDiscountLine.InventDimId
        outer join RecId, Symbol from unitOfMeasure
            where unitOfMeasure.RecId == periodicDiscountLine.UnitOfMeasure
        outer join pricingRuleHeader
            where periodicDiscount.HeaderPricingRule == pricingRuleHeader.RecId
        outer join RecId from pricingAttributeGroupHeader
            where pricingRuleHeader.PriceAttributeGroupName == pricingAttributeGroupHeader.Name
        outer join pricingRuleLine
            where periodicDiscountLine.LinePricingRule == pricingRuleLine.RecId
        outer join RecId from pricingAttributeGroupLine
            where pricingRuleLine.PriceAttributeGroupName == pricingAttributeGroupLine.Name
    {
        crtDiscount = this.ConvertToCrtPeriodicDiscountV2(periodicDiscount, periodicDiscountLine, unitOfMeasure, discountType, '', periodicDiscountLine.InventDimId);

        crtDiscount.ValidationPeriod = this.setCrtValidationPeriod(periodicDiscount, _validationPeriodLookup);
        crtDiscount.Dimension = GUPRetailPricingDataManager::ConvertToCrtInventoryDimension(inventDim);

        crtPricingComponentCode = this.ConvertToCrtPricingComponentCode(priceComponentCodeSetup, priceComponentCode);
        crtDiscount.PricingComponentCode = crtPricingComponentCode;

        this.setCrtPricingRuleAndPriorityForDiscount(
            crtDiscount, groupCombination.Priority,
            periodicDiscount.HeaderPricingRule, periodicDiscountLine.LinePricingRule);

        _priceDataList.Add(crtDiscount);

        this.addOfferIdToTmpOrderDataList(periodicDiscount.OfferId, offerIdSet);
    }

    tmpOrderDataInsertList.insertDatabase();
}

public System.Object GetFreeItemTiersByOfferIds(System.Object offerIds)
{
    GUPFreeItemDiscountTiers freeItemDiscountTiers;

    CLRObject crtFreeItemTierList = this.createCLRList(new Microsoft.Dynamics.Commerce.Runtime.DataModel.AttributeBasedPricing.FreeItemDiscountTier());

    while select dataValue from mTmpOrderData
            where mTmpOrderData.dataType == RetailTmpOrderDataType::OfferId
        join freeItemDiscountTiers
            where freeItemDiscountTiers.FreeItemId == mTmpOrderData.dataValue
    {
        crtFreeItemTierList.Add(this.ConvertToFreeItemDiscountTier(freeItemDiscountTiers));
    }

    return crtFreeItemTierList.AsReadOnly();
}

private Microsoft.Dynamics.Commerce.Runtime.DataModel.AttributeBasedPricing.FreeItemDiscountTier ConvertToFreeItemDiscountTier(GUPFreeItemDiscountTiers freeItemDiscountTiers)
{
    Microsoft.Dynamics.Commerce.Runtime.DataModel.AttributeBasedPricing.FreeItemDiscountTier crtFreeItemDiscountTier = new Microsoft.Dynamics.Commerce.Runtime.DataModel.AttributeBasedPricing.FreeItemDiscountTier();

    crtFreeItemDiscountTier.OfferId = freeItemDiscountTiers.FreeItemId;
    crtFreeItemDiscountTier.QtyOrAmountThreshold = freeItemDiscountTiers.QtyOrAmountThreshold;
    crtFreeItemDiscountTier.FreeItemQuantity = freeItemDiscountTiers.FreeItemQuantity;
    crtFreeItemDiscountTier.RecordId = int642Str(freeItemDiscountTiers.RecId);

    return crtFreeItemDiscountTier;
}

public System.Object GetFreeItemLinesByOfferIds(System.Object offerIds)
{
    GUPFreeItemLine freeItemLine;
    UnitOfMeasure unitOfMeasure;
    InventTable inventTable;
    InventTableModule inventTableModule;

    CLRObject crtFreeItemLineList = this.createCLRList(new Microsoft.Dynamics.Commerce.Runtime.DataModel.AttributeBasedPricing.FreeItemLine());
    ModuleInventPurchSales freeItemPriceModuleInventPurchSales = this.getFreeItemPriceModuleInvent();

    while select dataValue from mTmpOrderData
            where mTmpOrderData.dataType == RetailTmpOrderDataType::OfferId
        join freeItemLine
            where freeItemLine.FreeItemId == mTmpOrderData.dataValue
        join Symbol from unitOfMeasure
            where unitOfMeasure.RecId == freeItemLine.UnitOfMeasure
        join ItemId from inventTable
            where inventTable.Product == freeItemLine.Product
        join Price, UnitId, PriceUnit, Markup from inventTableModule
            where inventTableModule.ItemId == inventTable.ItemId
            && inventTableModule.ModuleType == freeItemPriceModuleInventPurchSales
    {
        crtFreeItemLineList.Add(this.ConvertToFreeItemLine(
            freeItemLine, unitOfMeasure.Symbol, inventTable.ItemId,
            inventTableModule.price,
            inventTableModule.UnitId,
            inventTableModule.PriceUnit,
            inventTableModule.Markup));
    }

    return crtFreeItemLineList.AsReadOnly();
}

private Microsoft.Dynamics.Commerce.Runtime.DataModel.AttributeBasedPricing.FreeItemLine ConvertToFreeItemLine(
    GUPFreeItemLine _freeItemLine,
    UnitOfMeasureSymbol _toUnitOfMeasureSymbol,
    ItemId _itemId,
    Price _price,
    UnitOfMeasureSymbol _fromUnitOfMeasureSymbol,
    PriceUnit _priceUnit,
    InventPriceMarkup _markup)
{
    Microsoft.Dynamics.Commerce.Runtime.DataModel.AttributeBasedPricing.FreeItemLine crtFreeItemLine = new Microsoft.Dynamics.Commerce.Runtime.DataModel.AttributeBasedPricing.FreeItemLine();

    crtFreeItemLine.OfferId = _freeItemLine.FreeItemId;
    crtFreeItemLine.FreeItemGroupId = _freeItemLine.FreeItemGroup;
    crtFreeItemLine.ItemId = _itemId;
    crtFreeItemLine.InventoryDimensionId = _freeItemLine.InventDimId;
    crtFreeItemLine.UnitOfMeasureSymbol = _toUnitOfMeasureSymbol;
    crtFreeItemLine.QuantityFactor = _freeItemLine.FreeItemLineQtyFactor;
    crtFreeItemLine.RecordId =  int642Str(_freeItemLine.RecId);

    PriceConvertFactory priceConvertFactory = PriceConvertFactory::newItemPrice(
        _itemId,
        _fromUnitOfMeasureSymbol,
        _price,
        _priceUnit,
        _markup,
        1,
        Ledger::accountingCurrency(CompanyInfo::current()));

    priceConvertFactory.parmNewUnitId(_toUnitOfMeasureSymbol);
    PriceConvert priceConvert = priceConvertFactory.priceConvert();
    crtFreeItemLine.Price = priceConvert.parmPrice();
    crtFreeItemLine.PriceUnit = _priceUnit;
    crtFreeItemLine.Quantity = 0;

    return crtFreeItemLine;
}
